const toEmail = found ? found[0] : (app.email || '');
const source = found
  ? '<div class="ok">Email address taken from the candidate\'s resume.</div>'
  : '<div class="banner">No email found in the resume' + (resumeText ? '' : ' (resume file not available)') + ', so the email from the application form is used. Please check it.</div>';
const company = job.company || 'our company';
const role = app.job_title || job.job_title || 'the role';

const html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Select candidate</title>' +
