  '<header><h1>Select ' + esc(app.candidate_name) + '</h1><p>' + esc(role) + ' · ' + esc(company) + ' · ' + esc(app.application_id) +
  (app.recommendation ? ' · AI verdict: ' + esc(app.recommendation) + ' (' + esc(app.match_score) + ')' : '') + '</p></header>' +
  '<div class="wrap">' + source +
  '<form class="card" method="POST" action="/webhook/send-mail">' +
    '<h2>Next steps for the candidate</h2><p class="sub">Fill in what applies. The AI agent writes the email from these details and sends it when you click <b>Accept</b>.</p>' +
    '<input type="hidden" name="id" value="' + esc(app.application_id) + '"><input type="hidden" name="type" value="select">' +
    '<label>To</label><input type="email" name="to" required value="' + esc(toEmail) + '">' +
    '<div class="row"><div><label>Next step</label><select name="next_step">' +
      ['Assignment', 'Interview round', 'Assignment + interview', 'Other'].map(o => '<option>' + o + '</option>').join('') +
    '</select></div><div><label>Deadline / date &amp; time</label><input type="text" name="deadline" placeholder="e.g. 10 Oct 2026, 6:00 PM IST"></div></div>' +
    '<label>Assignment / meeting link</label><input type="url" name="link" placeholder="https://...">' +
    '<label>Round details</label><textarea name="details" placeholder="e.g. 45-min product case interview with the PM team on Google Meet. Submit the assignment as a PDF by replying to this email."></textarea>' +
    '<label>Note for the AI (optional)</label><input type="text" name="note" placeholder="e.g. keep it short and friendly, mention we liked her HR-Buddy project">' +
    '<button class="green" type="submit" name="mode" value="send">Accept &amp; send</button>' +
    '<button class="ghost" type="submit" name="mode" value="preview">Preview AI email first</button>' +
    '<p class="note">At least one of link, deadline or round details is required.</p>' +
  '</form></div><p style="text-align:center"><a href="/webhook/results">Back to results</a></p></body></html>';
return [{ json: { html } }];

const esc = v => String(v ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
