  '</p><p><a href="/webhook/results">Back to results</a></p></div></body></html>';
return [{ json: { html: page('Application not found', 'This application ID does not exist.', '#dc2626') } }];

// Validate what the dashboard / select page posted
const b = $json.body || {};
const s = k => String(b[k] ?? '').trim();
const req = {
  id: s('id'), type: s('type'), to: s('to'), mode: s('mode') === 'preview' ? 'preview' : 'send',
  subject: s('subject'), message: String(b.message ?? ''),
  next_step: s('next_step'), deadline: s('deadline'), link: s('link'), details: s('details'), note: s('note'),
};
const errors = [];
if (!/^APP-[A-Z0-9]+$/.test(req.id)) errors.push('invalid application ID');
if (!['rejection', 'select', 'move_forward'].includes(req.type)) errors.push('unknown mail type');
if (req.to && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(req.to)) errors.push('invalid recipient email');
if (req.type === 'move_forward' && (!req.subject || !req.message.trim())) errors.push('subject and message are required');
if (req.type === 'select' && !req.link && !req.deadline && !req.details) errors.push('add at least a link, a deadline or round details');
if (req.link && !/^https?:\/\/\S+$/i.test(req.link)) errors.push('the link must start with http:// or https://');
return [{ json: { ...req, valid: errors.length === 0, error: errors.join(', ') } }];

// Recipient = address typed on the select page, else the email found in the resume, else the form email.
// Also blocks sending the same rejection twice.
const req = $('Check Send Request').first().json;
const app = $('Find Application').first().json;
const job = $('Find Job').first().json || {};
const resumeText = String($json.text || $json.data || '');
const found = resumeText.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const to = req.to || (found ? found[0] : '') || app.email || '';
const history = $('Get Mail History').all().map(i => i.json).filter(m => m.application_id);
const alreadyRejected = history.some(m => m.email_type === 'Rejection' && m.status === 'Sent');

const base = {
  ...req, to,
  application_id: app.application_id,
  vars: { candidate_name: app.candidate_name || 'Candidate', company_name: job.company || 'our company', role_name: app.job_title || job.job_title || 'the role' },
  ai_summary: app.ai_summary || '', strengths: app.strengths || '',
};
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to)) {
  return [{ json: { ...base, route: 'problem', status: 422, problem_title: 'No email address found', problem_text: 'Neither the resume nor the application form has a valid email address for this candidate.' } }];
}
if (req.type === 'rejection' && alreadyRejected) {
  return [{ json: { ...base, route: 'problem', status: 409, problem_title: 'Rejection already sent', problem_text: 'A rejection email was already sent to ' + to + ', so it was not sent again.' } }];
}
return [{ json: { ...base, route: req.type === 'select' ? 'ai' : 'direct' } }];

