// Take the AI's subject/body, or report the failure
const base = $('Resolve Recipient').first().json;
const out = $json.output || {};
if ($json.error || !String(out.body || '').trim()) {
  const err = typeof $json.error === 'string' ? $json.error : ($json.error?.message || 'the AI returned an empty email');
  return [{ json: { ...base, next: 'problem', status: 502, problem_title: 'AI could not write the email', problem_text: 'Error: ' + err + '. Nothing was sent. Go back and try again.' } }];
}
return [{ json: { ...base, subject: String(out.subject || '').trim() || 'Next steps: ' + base.vars.role_name + ' at ' + base.vars.company_name, message: String(out.body).trim(), next: base.mode } }];

