return [{ json: { html } }];

// Final email. Rejection always uses the fixed template; selection uses the AI / HR text.
// >>> The Gmail / SMTP address your SMTP credential logs in with <<<
const SENDER_EMAIL = 'your-email@gmail.com';

const REJECTION_SUBJECT = 'Update on your application for {{role_name}} at {{company_name}}';
const REJECTION_BODY = [
  'Dear {{candidate_name}},',
  '',
  'Thank you for your interest in the {{company_name}} and for taking the time to apply for the {{role_name}} position.',
  '',
  'After careful consideration, we\u2019ve decided not to move forward with your application at this stage. We appreciate your time and wish you the very best in your future opportunities.',
  '',
  'Best regards,',
  '{{company_name}} Hiring Team'
].join('\n');
const fill = (tpl, v) => String(tpl)
  .replace(/{{\s*candidate_name\s*}}/g, v.candidate_name)
  .replace(/{{\s*company_name\s*}}/g, v.company_name)
  .replace(/{{\s*role_name\s*}}/g, v.role_name);
const m = $json;
const isReject = m.type === 'rejection';
return [{ json: {
  application_id: m.application_id,
  email_type: isReject ? 'Rejection' : 'Selection',
  from: m.vars.company_name + ' Hiring Team <' + SENDER_EMAIL + '>',
  to_email: m.to,
  subject: fill(isReject ? REJECTION_SUBJECT : m.subject, m.vars),
  text: fill(isReject ? REJECTION_BODY : String(m.message).replace(/\r\n/g, '\n'), m.vars),
  candidate_name: m.vars.candidate_name
} }];

// One row per send attempt (success or failure) for the dashboard badge
const mail = $('Compose Email').first().json;
const err = $json.error ? (typeof $json.error === 'string' ? $json.error : ($json.error.message || JSON.stringify($json.error))) : '';
return [{ json: {
  application_id: mail.application_id,
  email_type: mail.email_type,
  to_email: mail.to_email,
  subject: mail.subject,
  sent_at: $now.toISO(),
  status: err ? 'Failed' : 'Sent',
  error: String(err).slice(0, 500)
} }];

